function normalizePilotPhone(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const digits = raw.replace(/[^0-9]/g, '');
  if (raw.startsWith('+')) return digits ? `+${digits}` : '';
  if (digits.startsWith('593')) return `+${digits}`;
  if (digits.startsWith('0') && digits.length === 10) return `+593${digits.slice(1)}`;
  if (digits.length === 9 && digits.startsWith('9')) return `+593${digits}`;
  return digits ? `+${digits}` : '';
}

function parseInboundPilotAllowlist(value) {
  const entries = String(value || '').split(',').map((entry) => entry.trim()).filter(Boolean);
  if (!entries.length) return { ok: false, reason: 'pilot_allowlist_missing', phones: [] };

  const phones = entries.map(normalizePilotPhone);
  if (phones.some((phone) => !/^\+[1-9][0-9]{7,14}$/.test(phone))) {
    return { ok: false, reason: 'pilot_allowlist_invalid', phones: [] };
  }
  return { ok: true, reason: null, phones: [...new Set(phones)] };
}

function evaluateInboundPilot(dryRunValue, allowlistValue, candidatePhone) {
  if (String(dryRunValue ?? 'true').trim().toLowerCase() !== 'false') {
    return { allowed: false, reason: 'inbound_dry_run', phone: null };
  }

  const allowlist = parseInboundPilotAllowlist(allowlistValue);
  if (!allowlist.ok) return { allowed: false, reason: allowlist.reason, phone: null };

  const phone = normalizePilotPhone(candidatePhone);
  if (!/^\+[1-9][0-9]{7,14}$/.test(phone)) {
    return { allowed: false, reason: 'pilot_phone_invalid', phone: null };
  }
  if (!allowlist.phones.includes(phone)) {
    return { allowed: false, reason: 'phone_not_allowlisted', phone };
  }
  return { allowed: true, reason: null, phone };
}

function inboundPilotFailure(result) {
  if (result.reason === 'phone_not_allowlisted') {
    return { httpStatus: 403, error: 'PHONE_NOT_ALLOWLISTED', message: 'El telefono no esta habilitado para el piloto inbound.' };
  }
  if (result.reason === 'pilot_phone_invalid') {
    return { httpStatus: 400, error: 'INVALID_PHONE', message: 'No se pudo normalizar el telefono del piloto.' };
  }
  return { httpStatus: 503, error: 'INBOUND_PILOT_DISABLED', message: 'El piloto inbound no esta habilitado.' };
}

const HANDOFF_REASONS = ["explicit_request","cancellation","sold_vehicle","complaint","tech_support","billing","new_sale","price_negotiation","home_payment","ownership_change","document_validation","unresolved_query"];

const OPPORTUNITY_STATUS_DB = {"interesado":"interested","interested":"interested","objecion":"objection","objection":"objection","no_interesado":"not_interested","not_interested":"not_interested"};

const REQUIRED_HANDOFF_FIELDS = ["full_name","phone","handoff_reason","conversation_summary","opportunity_status","promotion_communicated","contact_preference"];

function q(value) {
  return String(value ?? '').replace(/'/g, "''");
}

function sqlText(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return "'" + q(value) + "'";
}

function readHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return null;
}

function toE164(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (raw.startsWith('+')) return '+' + raw.replace(/[^0-9]/g, '');
  const digits = raw.replace(/[^0-9]/g, '');
  if (digits.startsWith('593')) return '+' + digits;
  if (digits.startsWith('0') && digits.length === 10) return '+593' + digits.slice(1);
  if (digits.length === 9 && digits.startsWith('9')) return '+593' + digits;
  return '+' + digits;
}

function validateHandoffEnvelope(body) {
  const reject = (error, message, extra = {}) => ({ ok: false, httpStatus: 400, error, message, extra });

  const missing = REQUIRED_HANDOFF_FIELDS.filter((key) => !Object.prototype.hasOwnProperty.call(body, key));
  if (missing.length) return reject('INVALID_REQUEST', 'Payload de handoff incompleto.', { missing_fields: missing });

  const handoffReason = String(body.handoff_reason || '').trim();
  if (!HANDOFF_REASONS.includes(handoffReason)) {
    return reject('INVALID_HANDOFF_REASON', 'handoff_reason no esta permitido.', { handoff_reason: handoffReason });
  }

  const opportunityStatusDb = OPPORTUNITY_STATUS_DB[String(body.opportunity_status || '').trim().toLowerCase()];
  if (!opportunityStatusDb) {
    return reject('INVALID_OPPORTUNITY_STATUS', 'opportunity_status no esta permitido.', { opportunity_status: body.opportunity_status });
  }

  const phone = toE164(body.phone);
  if (!/^\+[1-9][0-9]{7,14}$/.test(phone)) {
    return reject('INVALID_PHONE', 'phone debe estar en formato E.164.', { phone });
  }

  const conversationId = String(body.conversation_id || body.conv_id || '').trim();
  if (conversationId && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(conversationId)) {
    return reject('INVALID_CONVERSATION_ID', 'conversation_id debe ser UUID.', { conversation_id: conversationId });
  }

  const sourceMessageId = String(
    body.source_message_id || body.provider_message_id || body.wa_message_id || '',
  ).trim();
  if (!sourceMessageId) {
    return reject('SOURCE_MESSAGE_ID_REQUIRED', 'source_message_id es obligatorio para idempotencia.');
  }
  if (sourceMessageId && (sourceMessageId.length > 512 || /[\u0000-\u001f\u007f]/.test(sourceMessageId))) {
    return reject('INVALID_SOURCE_MESSAGE_ID', 'source_message_id no es valido.');
  }

  const requestedChatwootConversationId = String(body.chatwoot_conversation_id || '').trim();
  if (requestedChatwootConversationId && !/^[0-9]+$/.test(requestedChatwootConversationId)) {
    return reject('INVALID_CHATWOOT_CONVERSATION_ID', 'chatwoot_conversation_id debe ser numerico.');
  }

  const summary = String(body.conversation_summary || '').trim();
  if (!summary) return reject('INVALID_SUMMARY', 'conversation_summary no puede estar vacio.');

  return {
    ok: true,
    values: {
      fullName: String(body.full_name || ''),
      phone,
      handoffReason,
      summary,
      opportunityStatus: String(body.opportunity_status || ''),
      opportunityStatusDb,
      promotionCommunicated: String(body.promotion_communicated || ''),
      contactPreference: String(body.contact_preference || ''),
      // §9.1: área a la que corresponde el caso. Opcional y solo informativo:
      // va a la nota privada, nunca a SQL. Se acota y se limpia de controles
      // porque el endpoint lo puede llamar cualquier cliente autenticado.
      handoffArea: String(body.handoff_area || '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, 120),
      conversationId: conversationId || null,
      sourceMessageId: sourceMessageId || null,
      requestedChatwootConversationId,
      source: String(body.source || 'unknown'),
    },
  };
}

function buildResolveSql(values, schema) {
  return "SET search_path TO " + schema + ", public;\n" +
"WITH input AS (\n" +
"  SELECT " + (values.conversationId ? "'" + q(values.conversationId) + "'::uuid" : "NULL::uuid") + " AS requested_conversation_id,\n" +
"         '" + q(values.phone) + "'::text AS phone,\n" +
"         " + sqlText(values.sourceMessageId) + "::text AS source_message_id,\n" +
"         " + sqlText(values.requestedChatwootConversationId) + "::text AS requested_chatwoot_conversation_id,\n" +
"         " + sqlText(values.fullName) + "::text AS full_name,\n" +
"         '" + q(values.handoffReason) + "'::text AS handoff_reason,\n" +
"         '" + q(values.summary) + "'::text AS conversation_summary,\n" +
"         '" + q(values.opportunityStatus) + "'::text AS opportunity_status,\n" +
"         '" + q(values.opportunityStatusDb) + "'::text AS opportunity_status_db,\n" +
"         " + sqlText(values.promotionCommunicated) + "::text AS promotion_communicated,\n" +
"         " + sqlText(values.contactPreference) + "::text AS contact_preference,\n" +
// El nodo Postgres reemplaza $json con la fila del resultado, así que lo que no
// se proyecte acá no llega al nodo que arma la nota. Un smoke real lo mostró:
// el área viajaba en el payload y en la auditoría, pero la nota del asesor
// llegaba con "Area: -".
"         " + sqlText(values.handoffArea) + "::text AS handoff_area,\n" +
"         " + sqlText(values.source) + "::text AS source\n" +
"), advisor_route AS (\n" +
"  SELECT * FROM resolve_inbound_advisor((SELECT phone FROM input))\n" +
"), by_requested AS (\n" +
"  SELECT c.id, c.customer_id, c.status, c.chatwoot_conversation_id, cu.salesforce_contact_id, cu.salesforce_opportunity_id, cu.salesforce_contract_id, cu.salesforce_vehicle_id, cu.full_name AS customer_full_name, cu.phone AS customer_phone, cu.vehicle_brand, cu.vehicle_model, cu.service_name, cu.gps_status, cu.opportunity_stage, cu.opportunity_closed\n" +
"  FROM conversations c JOIN quicklink_account_assignments cu ON cu.id = c.customer_id JOIN input i ON i.requested_conversation_id = c.id AND i.phone = cu.phone\n" +
"  WHERE i.requested_conversation_id IS NOT NULL AND NOT COALESCE((SELECT multi_match FROM advisor_route), false)\n" +
"  LIMIT 1\n" +
"), by_phone_existing AS (\n" +
"  SELECT c.id, c.customer_id, c.status, c.chatwoot_conversation_id, cu.salesforce_contact_id, cu.salesforce_opportunity_id, cu.salesforce_contract_id, cu.salesforce_vehicle_id, cu.full_name AS customer_full_name, cu.phone AS customer_phone, cu.vehicle_brand, cu.vehicle_model, cu.service_name, cu.gps_status, cu.opportunity_stage, cu.opportunity_closed\n" +
"  FROM conversations c JOIN quicklink_account_assignments cu ON cu.id = c.customer_id JOIN input i ON i.phone = cu.phone\n" +
"  WHERE i.requested_conversation_id IS NULL AND NOT EXISTS (SELECT 1 FROM by_requested) AND NOT COALESCE((SELECT multi_match FROM advisor_route), false) AND c.status IN ('bot_active','handed_off')\n" +
"  ORDER BY c.created_at DESC\n" +
"  LIMIT 1\n" +
"), by_phone_customer AS (\n" +
"  SELECT cu.* FROM quicklink_account_assignments cu JOIN input i ON i.phone = cu.phone AND cu.deleted_at IS NULL\n" +
"  WHERE i.requested_conversation_id IS NULL AND NOT EXISTS (SELECT 1 FROM by_requested) AND NOT EXISTS (SELECT 1 FROM by_phone_existing) AND NOT COALESCE((SELECT multi_match FROM advisor_route), false)\n" +
"  LIMIT 1\n" +
"), by_customer_candidate AS (\n" +
"  SELECT NULL::uuid AS id, cu.id AS customer_id, NULL::conversation_status AS status, NULL::text AS chatwoot_conversation_id,\n" +
"         cu.salesforce_contact_id, cu.salesforce_opportunity_id, cu.salesforce_contract_id, cu.salesforce_vehicle_id,\n" +
"         cu.full_name AS customer_full_name, cu.phone AS customer_phone, cu.vehicle_brand, cu.vehicle_model,\n" +
"         cu.service_name, cu.gps_status, cu.opportunity_stage, cu.opportunity_closed\n" +
"    FROM by_phone_customer cu\n" +
"), resolved AS (\n" +
"  SELECT * FROM by_requested\n" +
"  UNION ALL SELECT * FROM by_phone_existing\n" +
"  UNION ALL SELECT * FROM by_customer_candidate\n" +
"  LIMIT 1\n" +
"), external_lock AS MATERIALIZED (\n" +
"  SELECT external_claim.* FROM input i\n" +
"  CROSS JOIN LATERAL claim_chatwoot_conversation_id(NULL::uuid, i.requested_chatwoot_conversation_id) external_claim\n" +
"  WHERE i.requested_chatwoot_conversation_id IS NOT NULL\n" +
"), created_conversation AS MATERIALIZED (\n" +
"  INSERT INTO conversations AS conversation (customer_id, status, summary)\n" +
"  SELECT resolved.customer_id, 'bot_active'::conversation_status, 'Handoff iniciado por WF-04 DEV'\n" +
"    FROM resolved LEFT JOIN external_lock ON true\n" +
"   WHERE resolved.id IS NULL AND resolved.customer_id IS NOT NULL\n" +
"  ON CONFLICT (customer_id) WHERE status IN ('bot_active', 'handed_off')\n" +
"  DO UPDATE SET customer_id = EXCLUDED.customer_id\n" +
"  RETURNING conversation.id, conversation.customer_id, conversation.status, conversation.chatwoot_conversation_id\n" +
"), resolved_local AS MATERIALIZED (\n" +
"  SELECT COALESCE(resolved.id, created.id) AS id, resolved.customer_id,\n" +
"         COALESCE(resolved.status, created.status) AS status,\n" +
"         COALESCE(resolved.chatwoot_conversation_id, created.chatwoot_conversation_id) AS chatwoot_conversation_id,\n" +
"         resolved.salesforce_contact_id, resolved.salesforce_opportunity_id, resolved.salesforce_contract_id, resolved.salesforce_vehicle_id,\n" +
"         resolved.customer_full_name, resolved.customer_phone, resolved.vehicle_brand, resolved.vehicle_model, resolved.service_name,\n" +
"         resolved.gps_status, resolved.opportunity_stage, resolved.opportunity_closed\n" +
"    FROM resolved LEFT JOIN created_conversation created ON true\n" +
"), correlation_claim AS MATERIALIZED (\n" +
"  SELECT claim.* FROM input i JOIN resolved_local r ON r.id IS NOT NULL\n" +
"  CROSS JOIN LATERAL claim_chatwoot_conversation_id(\n" +
"    r.id, COALESCE(i.requested_chatwoot_conversation_id, r.chatwoot_conversation_id)\n" +
"  ) claim\n" +
"  WHERE COALESCE(i.requested_chatwoot_conversation_id, r.chatwoot_conversation_id) IS NOT NULL\n" +
"    AND (i.requested_chatwoot_conversation_id IS NULL OR r.chatwoot_conversation_id IS NULL OR i.requested_chatwoot_conversation_id = r.chatwoot_conversation_id)\n" +
"), correlation_state AS MATERIALIZED (\n" +
"  SELECT\n" +
"    CASE WHEN r.id IS NULL THEN false\n" +
"         WHEN COALESCE(i.requested_chatwoot_conversation_id, r.chatwoot_conversation_id) IS NULL THEN false\n" +
"         WHEN i.requested_chatwoot_conversation_id IS NOT NULL AND r.chatwoot_conversation_id IS NOT NULL AND i.requested_chatwoot_conversation_id <> r.chatwoot_conversation_id THEN true\n" +
"         ELSE NOT COALESCE((SELECT claimed FROM correlation_claim), false) END AS conflicting,\n" +
"    CASE WHEN r.id IS NOT NULL AND (\n" +
"           (i.requested_chatwoot_conversation_id IS NOT NULL AND r.chatwoot_conversation_id IS NOT NULL AND i.requested_chatwoot_conversation_id <> r.chatwoot_conversation_id)\n" +
"           OR (COALESCE(i.requested_chatwoot_conversation_id, r.chatwoot_conversation_id) IS NOT NULL AND NOT COALESCE((SELECT claimed FROM correlation_claim), false))\n" +
"         ) THEN NULL ELSE COALESCE(i.requested_chatwoot_conversation_id, r.chatwoot_conversation_id) END AS runtime_chatwoot_conversation_id,\n" +
"    r.chatwoot_conversation_id AS stored_chatwoot_conversation_id\n" +
"  FROM input i LEFT JOIN resolved_local r ON true\n" +
"), handoff_operation AS MATERIALIZED (\n" +
"  SELECT operation.* FROM input i LEFT JOIN resolved_local r ON true\n" +
"  CROSS JOIN correlation_state state\n" +
"  CROSS JOIN LATERAL begin_chatwoot_handoff_operation(\n" +
"    r.id,\n" +
"    CASE WHEN r.id IS NOT NULL THEN 'conversation:' || r.id::text\n" +
"         WHEN state.runtime_chatwoot_conversation_id IS NOT NULL THEN 'chatwoot:' || state.runtime_chatwoot_conversation_id\n" +
"         ELSE 'multimatch:' || md5(i.phone) END,\n" +
"    i.source_message_id, state.runtime_chatwoot_conversation_id\n" +
"  ) operation\n" +
"  WHERE NOT state.conflicting\n" +
"    AND (r.id IS NOT NULL OR COALESCE((SELECT multi_match FROM advisor_route), false))\n" +
")\n" +
"SELECT i.*, r.id::text AS conversation_id, r.customer_id::text AS customer_id, r.status::text AS current_conversation_status,\n" +
"       state.runtime_chatwoot_conversation_id AS chatwoot_conversation_id,\n" +
"       state.stored_chatwoot_conversation_id AS stored_chatwoot_conversation_id,\n" +
"       state.conflicting AS chatwoot_conversation_conflict,\n" +
"       COALESCE((SELECT acquired FROM handoff_operation), false) AS handoff_operation_acquired,\n" +
"       (SELECT operation_status FROM handoff_operation) AS handoff_operation_status,\n" +
"       (SELECT operation_token::text FROM handoff_operation) AS handoff_operation_token,\n" +
"       r.salesforce_contact_id, r.salesforce_opportunity_id, r.salesforce_contract_id, r.salesforce_vehicle_id, COALESCE(NULLIF(i.full_name, ''), r.customer_full_name, 'Cliente') AS resolved_full_name, COALESCE(r.customer_phone, i.phone) AS resolved_phone, r.vehicle_brand, r.vehicle_model, r.service_name, r.gps_status::text AS gps_status, r.opportunity_stage, COALESCE(r.opportunity_closed, false) AS opportunity_closed\n" +
", (SELECT chatwoot_agent_id FROM advisor_route) AS advisor_chatwoot_agent_id"
  + ", (SELECT advisor_name FROM advisor_route) AS advisor_name"
  + ", (SELECT salesforce_user_id FROM advisor_route) AS advisor_sf_user_id"
  + ", (SELECT is_supervisor FROM advisor_route) AS advisor_is_supervisor"
  + ", (SELECT routes_to FROM advisor_route) AS advisor_routes_to"
  + ", (SELECT multi_match FROM advisor_route) AS advisor_multi_match"
  + "\nFROM input i LEFT JOIN resolved_local r ON true CROSS JOIN correlation_state state";
}

const startedAt = Date.now();
const input = $json ?? {};
// WF-03 posts through the webhook; a manual execution passes the fields flat.
const body = input.body && typeof input.body === 'object' ? input.body : input;
const headers = input.headers || {};
const SCHEMA = "renovation_dev";

function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}
function done(extra) {
  return [{ json: { duration_ms: Date.now() - startedAt, ...extra } }];
}
function fail(httpStatus, error, message, extra = {}) {
  return done({ success: false, request_valid: false, persist_required: false, http_status: httpStatus, error, message, ...extra });
}

const expectedToken = env('RENOV_INTERNAL_TOKEN');
if (!expectedToken) return fail(500, 'CONFIG_ERROR', 'RENOV_INTERNAL_TOKEN no esta configurado en n8n.');
const auth = String(readHeader(headers, 'authorization') || '');
const bearer = auth.match(/^Bearer\s+(.+)$/i)?.[1] || null;
const providedToken = readHeader(headers, 'x-internal-token') || bearer;
if (providedToken !== expectedToken) return fail(401, 'UNAUTHORIZED', 'Token interno invalido.');

const validated = validateHandoffEnvelope(body);
if (!validated.ok) return fail(validated.httpStatus, validated.error, validated.message, validated.extra);

const values = validated.values;
const pilot = evaluateInboundPilot(
  env('RENOV_DEV_INBOUND_DRY_RUN_SENDS', 'true'),
  env('RENOV_DEV_INBOUND_PILOT_ALLOWED_PHONES', ''),
  values.phone,
);
if (!pilot.allowed) {
  const blocked = inboundPilotFailure(pilot);
  return fail(blocked.httpStatus, blocked.error, blocked.message, { pilot_block_reason: pilot.reason });
}
return done({
  success: true,
  request_valid: true,
  persist_required: false,
  http_status: 200,
  full_name: values.fullName,
  phone: values.phone,
  handoff_reason: values.handoffReason,
  conversation_summary: values.summary,
  opportunity_status: values.opportunityStatus,
  opportunity_status_db: values.opportunityStatusDb,
  promotion_communicated: values.promotionCommunicated,
  contact_preference: values.contactPreference,
  handoff_area: values.handoffArea,
  conversation_id: values.conversationId,
  source_message_id: values.sourceMessageId,
  source: values.source,
  resolve_sql: buildResolveSql(values, SCHEMA),
});

function normalizePilotPhone(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const digits = raw.replace(/[^0-9]/g, '');
  if (raw.startsWith('+')) return digits ? `+${digits}` : '';
  if (digits.startsWith('593')) return `+${digits}`;
  if (digits.startsWith('0') && digits.length === 10) return `+593${digits.slice(1)}`;
  if (digits.length === 9 && digits.startsWith('9')) return `+593${digits}`;
  return digits ? `+${digits}` : '';
}

function parseInboundPilotAllowlist(value) {
  const entries = String(value || '').split(',').map((entry) => entry.trim()).filter(Boolean);
  if (!entries.length) return { ok: false, reason: 'pilot_allowlist_missing', phones: [] };

  const phones = entries.map(normalizePilotPhone);
  if (phones.some((phone) => !/^\+[1-9][0-9]{7,14}$/.test(phone))) {
    return { ok: false, reason: 'pilot_allowlist_invalid', phones: [] };
  }
  return { ok: true, reason: null, phones: [...new Set(phones)] };
}

function evaluateInboundPilot(dryRunValue, allowlistValue, candidatePhone) {
  if (String(dryRunValue ?? 'true').trim().toLowerCase() !== 'false') {
    return { allowed: false, reason: 'inbound_dry_run', phone: null };
  }

  const allowlist = parseInboundPilotAllowlist(allowlistValue);
  if (!allowlist.ok) return { allowed: false, reason: allowlist.reason, phone: null };

  const phone = normalizePilotPhone(candidatePhone);
  if (!/^\+[1-9][0-9]{7,14}$/.test(phone)) {
    return { allowed: false, reason: 'pilot_phone_invalid', phone: null };
  }
  if (!allowlist.phones.includes(phone)) {
    return { allowed: false, reason: 'phone_not_allowlisted', phone };
  }
  return { allowed: true, reason: null, phone };
}

function inboundPilotFailure(result) {
  if (result.reason === 'phone_not_allowlisted') {
    return { httpStatus: 403, error: 'PHONE_NOT_ALLOWLISTED', message: 'El telefono no esta habilitado para el piloto inbound.' };
  }
  if (result.reason === 'pilot_phone_invalid') {
    return { httpStatus: 400, error: 'INVALID_PHONE', message: 'No se pudo normalizar el telefono del piloto.' };
  }
  return { httpStatus: 503, error: 'INBOUND_PILOT_DISABLED', message: 'El piloto inbound no esta habilitado.' };
}

function q(value) {
  return String(value ?? '').replace(/'/g, "''");
}

function sqlText(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return "'" + q(value) + "'";
}

function sqlJson(value) {
  return "'" + q(JSON.stringify(value || {})) + "'::jsonb";
}

function asInt(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? Math.trunc(n) : null;
}

function safeError(error) {
  if (!error) return 'unknown_error';
  if (error.message) return String(error.message).slice(0, 500);
  try { return JSON.stringify(error).slice(0, 500); } catch (e) { return String(error).slice(0, 500); }
}

function extractContactId(body) {
  return asInt(body?.payload?.contact?.id || body?.payload?.id || body?.contact?.id || body?.id || body?.data?.id || body?.contact_id);
}

function extractConversationId(body) {
  return asInt(body?.payload?.id || body?.conversation?.id || body?.id || body?.data?.id || body?.conversation_id);
}

function firstContact(body) {
  const payload = body?.payload || body?.data?.payload || body?.contacts || body?.data || [];
  const list = Array.isArray(payload) ? payload : (Array.isArray(payload?.contacts) ? payload.contacts : []);
  return list[0] || null;
}

function isSupervisorOnlyHandoff(item) {
  return !item.conversation_id
    && (item.advisor_multi_match === true || item.advisor_multi_match === 't');
}

function assignmentSucceeded(assignmentStatus) {
  return assignmentStatus === 'success:advisor' || String(assignmentStatus).startsWith('success:team');
}

function buildHandoffLabels(item) {
  const reason = String(item.handoff_reason || 'unknown').replace(/[^a-z0-9_]+/g, '_');
  const labels = ['renovaciones_handoff', 'renovaciones_' + reason];
  return labels;
}

function buildAdvisorMention(item) {
  const agentId = asInt(item.advisor_chatwoot_agent_id);
  // `advisor_name` es el nombre que proyecta `buildResolveSql`. No inventar otro:
  // un campo inexistente deja la mencion en null para siempre y en silencio.
  const name = String(item.advisor_name || '').replace(/[\u0000-\u001f\u007f[\]()]/g, ' ').trim();
  if (!agentId || !name) return null;
