function buildPersistSql(item, outcome, schema) {
  return "SET search_path TO " + schema + ", public;\n" +
"WITH input AS (\n" +
"  SELECT '" + q(item.conversation_id) + "'::uuid AS conversation_id,\n" +
"         '" + q(item.source_message_id) + "'::text AS request_id,\n" +
"         '" + q(item.handoff_operation_token) + "'::uuid AS operation_token,\n" +
"         '" + q(item.handoff_reason) + "'::handoff_reason AS handoff_reason,\n" +
"         '" + q(item.opportunity_status_db) + "'::opportunity_status AS opportunity_status,\n" +
"         " + sqlText(item.conversation_summary) + "::text AS conversation_summary,\n" +
"         " + sqlText(item.promotion_communicated) + "::text AS promotion_communicated,\n" +
"         " + sqlText(item.contact_preference) + "::text AS contact_preference,\n" +
"         '" + q(String(outcome.chatwootConversationId)) + "'::text AS chatwoot_conversation_id,\n" +
"         '" + q(outcome.clientMessage) + "'::text AS client_message,\n" +
"         " + outcome.responseCode + "::integer AS response_code,\n" +
"         '" + q(outcome.salesforceStatus) + "'::text AS salesforce_status,\n" +
"         " + (outcome.salesforceHttpStatus ? Number(outcome.salesforceHttpStatus) : 'NULL') + "::integer AS salesforce_http_status,\n" +
"         " + sqlText(outcome.salesforceError) + "::text AS salesforce_error,\n" +
"         " + sqlJson(buildLogPayload(item, outcome)) + " AS log_payload,\n" +
"         " + sqlJson(buildSalesforceLogPayload(item, outcome)) + " AS salesforce_log_payload\n" +
"), target AS MATERIALIZED (\n" +
"  SELECT c.id, c.customer_id, c.status, c.chatwoot_conversation_id FROM conversations c, input WHERE c.id = input.conversation_id\n" +
"), correlation_claim AS MATERIALIZED (\n" +
"  SELECT claim.* FROM input JOIN target ON true\n" +
"  CROSS JOIN LATERAL claim_chatwoot_conversation_id(target.id, input.chatwoot_conversation_id) claim\n" +
"), locked_target AS MATERIALIZED (\n" +
"  SELECT c.id, c.customer_id, c.status, c.chatwoot_conversation_id\n" +
"    FROM conversations c, input LEFT JOIN correlation_claim ON true\n" +
"   WHERE c.id = input.conversation_id\n" +
"   FOR UPDATE\n" +
"), operation_current AS MATERIALIZED (\n" +
"  SELECT is_chatwoot_handoff_operation_current(input.request_id, input.operation_token) AS current\n" +
"    FROM input LEFT JOIN locked_target ON true\n" +
"), conflict AS (\n" +
"  SELECT NOT EXISTS (SELECT 1 FROM locked_target)\n" +
"      OR NOT COALESCE((SELECT claimed FROM correlation_claim), false)\n" +
"      OR NOT COALESCE((SELECT current FROM operation_current), false)\n" +
"      OR EXISTS (SELECT 1 FROM locked_target, input WHERE locked_target.chatwoot_conversation_id IS NOT NULL AND locked_target.chatwoot_conversation_id <> input.chatwoot_conversation_id) AS conflicting\n" +
"), updated AS (\n" +
"  UPDATE conversations c\n" +
"     SET status = 'handed_off'::conversation_status,\n" +
"         handoff_reason = input.handoff_reason,\n" +
"         chatwoot_conversation_id = input.chatwoot_conversation_id,\n" +
"         opportunity_status = input.opportunity_status,\n" +
"         promotion_communicated = input.promotion_communicated,\n" +
"         contact_preference = input.contact_preference,\n" +
"         summary = input.conversation_summary,\n" +
"         handed_off_at = now(),\n" +
"         closed_at = NULL\n" +
"    FROM input\n" +
"   WHERE c.id = input.conversation_id\n" +
"     AND c.status = 'bot_active'::conversation_status\n" +
"     AND NOT COALESCE((SELECT conflicting FROM conflict), false)\n" +
"     AND (c.chatwoot_conversation_id IS NULL OR c.chatwoot_conversation_id = input.chatwoot_conversation_id)\n" +
"  RETURNING c.id, c.customer_id, c.status, c.chatwoot_conversation_id\n" +
"), operation_finished AS MATERIALIZED (\n" +
"  SELECT finish_chatwoot_handoff_operation(\n" +
"    input.request_id, input.operation_token,\n" +
"    CASE WHEN EXISTS (SELECT 1 FROM updated) THEN 'completed' ELSE 'uncertain' END,\n" +
"    input.chatwoot_conversation_id\n" +
"  ) AS finished FROM input\n" +
"), paused AS (\n" +
"  SELECT pause_customer_campaigns(customer_id, 'handoff') AS paused FROM updated\n" +
"), handoff_log AS (\n" +
"  INSERT INTO interaction_logs (customer_id, conversation_id, event_type, correlation_id, payload, success)\n" +
"  SELECT updated.customer_id, updated.id, 'chatwoot_handoff', input.chatwoot_conversation_id, input.log_payload, true FROM updated, input\n" +
"), salesforce_log AS (\n" +
"  INSERT INTO interaction_logs (customer_id, conversation_id, event_type, correlation_id, payload, success, error_message)\n" +
"  SELECT updated.customer_id, updated.id, 'salesforce_handoff_patch', input.chatwoot_conversation_id, input.salesforce_log_payload, input.salesforce_status = 'success', CASE WHEN input.salesforce_status = 'success' THEN NULL ELSE COALESCE(input.salesforce_error, 'SALESFORCE_DEV_HANDOFF_URL not configured') END FROM updated, input\n" +
"), conflict_log AS (\n" +
"  INSERT INTO interaction_logs (customer_id, conversation_id, event_type, correlation_id, payload, success, error_message)\n" +
"  SELECT locked_target.customer_id, locked_target.id, 'chatwoot_handoff_conflict', input.chatwoot_conversation_id,\n" +
"         jsonb_build_object('workflow', 'REN-DEV-WF-04', 'reason', 'handoff_fence_rejected'), false, 'CHATWOOT_HANDOFF_CONFLICT'\n" +
"    FROM locked_target, input WHERE COALESCE((SELECT conflicting FROM conflict), false)\n" +
")\n" +
"SELECT (updated.id IS NOT NULL AND operation_finished.finished) AS success, COALESCE(updated.id, locked_target.id)::text AS conversation_id, input.chatwoot_conversation_id,\n" +
"       COALESCE(updated.chatwoot_conversation_id, locked_target.chatwoot_conversation_id) AS stored_chatwoot_conversation_id,\n" +
"       COALESCE(updated.chatwoot_conversation_id = input.chatwoot_conversation_id, false) AS chatwoot_conversation_reconciled,\n" +
"       COALESCE(updated.status, locked_target.status)::text AS conversation_status,\n" +
"       CASE WHEN updated.id IS NOT NULL THEN input.client_message ELSE '' END AS client_message,\n" +
"       CASE WHEN updated.id IS NOT NULL AND operation_finished.finished THEN input.response_code WHEN locked_target.id IS NULL THEN 404 ELSE 409 END AS response_code,\n" +
"       input.salesforce_status, input.salesforce_http_status,\n" +
"       CASE WHEN updated.id IS NOT NULL AND operation_finished.finished THEN NULL WHEN locked_target.id IS NULL THEN 'CONVERSATION_NOT_FOUND' ELSE 'CHATWOOT_HANDOFF_CONFLICT' END AS error,\n" +
"       COALESCE((SELECT bool_or(paused) FROM paused), false) AS campaign_paused\n" +
"  FROM input LEFT JOIN locked_target ON true LEFT JOIN updated ON true CROSS JOIN operation_finished";
}

function buildFailurePersistSql(
  item,
  chatwootConversationId,
  operationStatus,
  responseCode,
  errorCode,
  schema,
) {
  const conversationIdSql = item.conversation_id
    ? "'" + q(item.conversation_id) + "'::uuid"
    : 'NULL::uuid';
  return "SET search_path TO " + schema + ", public;\n" +
"WITH input AS (\n" +
"  SELECT " + conversationIdSql + " AS conversation_id,\n" +
"         '" + q(item.source_message_id) + "'::text AS request_id,\n" +
"         '" + q(item.handoff_operation_token) + "'::uuid AS operation_token,\n" +
"         " + sqlText(chatwootConversationId ? String(chatwootConversationId) : null) + "::text AS chatwoot_conversation_id,\n" +
"         '" + q(operationStatus) + "'::text AS operation_status\n" +
"), target AS MATERIALIZED (\n" +
"  SELECT conversation.id, conversation.customer_id, conversation.status, conversation.chatwoot_conversation_id\n" +
"    FROM conversations conversation, input WHERE conversation.id = input.conversation_id\n" +
"), correlation_claim AS MATERIALIZED (\n" +
"  SELECT claim.* FROM input JOIN target ON true\n" +
"  CROSS JOIN LATERAL claim_chatwoot_conversation_id(target.id, input.chatwoot_conversation_id) claim\n" +
"), locked_target AS MATERIALIZED (\n" +
"  SELECT conversation.id, conversation.customer_id, conversation.status, conversation.chatwoot_conversation_id\n" +
"    FROM conversations conversation, input LEFT JOIN correlation_claim ON true\n" +
"   WHERE conversation.id = input.conversation_id\n" +
"   FOR UPDATE\n" +
"), operation_current AS MATERIALIZED (\n" +
"  SELECT is_chatwoot_handoff_operation_current(input.request_id, input.operation_token) AS current\n" +
"    FROM input LEFT JOIN locked_target ON true\n" +
"), correlated AS (\n" +
"  UPDATE conversations conversation\n" +
"     SET chatwoot_conversation_id = input.chatwoot_conversation_id\n" +
"    FROM input\n" +
"   WHERE conversation.id = input.conversation_id\n" +
"     AND input.chatwoot_conversation_id IS NOT NULL\n" +
"     AND COALESCE((SELECT current FROM operation_current), false)\n" +
"     AND COALESCE((SELECT claimed FROM correlation_claim), false)\n" +
"     AND (conversation.chatwoot_conversation_id IS NULL OR conversation.chatwoot_conversation_id = input.chatwoot_conversation_id)\n" +
"  RETURNING conversation.id\n" +
"), operation_finished AS MATERIALIZED (\n" +
"  SELECT finish_chatwoot_handoff_operation(\n" +
"    input.request_id, input.operation_token,\n" +
"    input.operation_status, input.chatwoot_conversation_id\n" +
"  ) AS finished FROM input\n" +
"), failure_log AS (\n" +
"  INSERT INTO interaction_logs (customer_id, conversation_id, event_type, correlation_id, payload, success, error_message)\n" +
"  SELECT locked_target.customer_id, locked_target.id, 'chatwoot_handoff_failed', input.request_id,\n" +
"         jsonb_build_object('workflow', 'REN-DEV-WF-04', 'operation_status', input.operation_status, 'chatwoot_id_known', input.chatwoot_conversation_id IS NOT NULL),\n" +
"         false, '" + q(errorCode) + "'\n" +
"    FROM input LEFT JOIN locked_target ON true\n" +
")\n" +
"SELECT false AS success, locked_target.id::text AS conversation_id, input.chatwoot_conversation_id,\n" +
"       locked_target.chatwoot_conversation_id AS stored_chatwoot_conversation_id,\n" +
"       false AS chatwoot_conversation_reconciled, locked_target.status::text AS conversation_status,\n" +
"       ''::text AS client_message, " + Number(responseCode) + "::integer AS response_code, 'skipped'::text AS salesforce_status,\n" +
"       NULL::integer AS salesforce_http_status, '" + q(errorCode) + "'::text AS error, false AS campaign_paused\n" +
"  FROM input LEFT JOIN locked_target ON true CROSS JOIN operation_finished";
}

function buildExternalPersistSql(item, outcome, schema) {
  return "SET search_path TO " + schema + ", public;\n" +
"WITH input AS (\n" +
"  SELECT '" + q(item.source_message_id) + "'::text AS request_id,\n" +
"         '" + q(item.handoff_operation_token) + "'::uuid AS operation_token,\n" +
"         '" + q(String(outcome.chatwootConversationId)) + "'::text AS chatwoot_conversation_id\n" +
"), operation_current AS MATERIALIZED (\n" +
"  SELECT is_chatwoot_handoff_operation_current(input.request_id, input.operation_token) AS current FROM input\n" +
"), operation_finished AS MATERIALIZED (\n" +
"  SELECT finish_chatwoot_handoff_operation(input.request_id, input.operation_token, 'completed', input.chatwoot_conversation_id) AS finished\n" +
"    FROM input WHERE COALESCE((SELECT current FROM operation_current), false)\n" +
"), logged AS (\n" +
"  INSERT INTO interaction_logs (customer_id, conversation_id, event_type, correlation_id, payload, success)\n" +
"  SELECT NULL, NULL, 'chatwoot_handoff_ambiguous', input.request_id, " + sqlJson(buildLogPayload(item, outcome)) + ", true\n" +
"    FROM input, operation_finished WHERE operation_finished.finished\n" +
"  RETURNING id\n" +
") SELECT COALESCE(operation_finished.finished, false) AS success, NULL::text AS conversation_id, input.chatwoot_conversation_id,\n" +
"         CASE WHEN operation_finished.finished THEN 'handed_off_external' ELSE 'handoff_conflict' END::text AS conversation_status,\n" +
"         CASE WHEN operation_finished.finished THEN '" + q(outcome.clientMessage) + "' ELSE '' END::text AS client_message,\n" +
"         CASE WHEN operation_finished.finished THEN " + outcome.responseCode + " ELSE 409 END::integer AS response_code,\n" +
"         'skipped'::text AS salesforce_status, NULL::integer AS salesforce_http_status,\n" +
"         CASE WHEN operation_finished.finished THEN NULL ELSE 'CHATWOOT_HANDOFF_CONFLICT' END::text AS error\n" +
"    FROM input LEFT JOIN operation_finished ON true;";
}

const startedAt = Date.now();
const item = $json;
const SCHEMA = "renovation_dev";
const CLIENT_MESSAGE = "Listo, le derivé con un asesor de Quicklink. Enseguida continuará la atención por este medio.";

function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}
function done(extra) {
  return [{ json: { ...item, duration_ms: Date.now() - startedAt, ...extra } }];
}
function fail(httpStatus, error, message, extra = {}) {
  return done({ success: false, persist_required: false, http_status: httpStatus, error, message, ...extra });
}
function failReserved(httpStatus, error, message, extra = {}, operationStatus = 'failed', chatwootConversationId = null) {
  if (!item.handoff_operation_token) return fail(httpStatus, error, message, extra);
  return done({
    success: false,
    persist_required: true,
    http_status: httpStatus,
    error,
    message,
    ...extra,
    persist_sql: buildFailurePersistSql(
      item,
      chatwootConversationId,
      operationStatus,
      httpStatus,
      error,
      SCHEMA,
    ),
  });
}

const pilot = evaluateInboundPilot(
  env('RENOV_DEV_INBOUND_DRY_RUN_SENDS', 'true'),
  env('RENOV_DEV_INBOUND_PILOT_ALLOWED_PHONES', ''),
  item.resolved_phone || item.phone || '',
);
if (!pilot.allowed) {
  const blocked = inboundPilotFailure(pilot);
  return failReserved(blocked.httpStatus, blocked.error, blocked.message, { pilot_block_reason: pilot.reason });
}

const chatwootConversationConflict = item.chatwoot_conversation_conflict === true
  || item.chatwoot_conversation_conflict === 't'
  || item.chatwoot_conversation_conflict === 'true';
if (chatwootConversationConflict) {
  return fail(409, 'CHATWOOT_CONVERSATION_CONFLICT', 'La conversación de Chatwoot ya está correlacionada con otro cliente.');
}

const supervisorOnlyHandoff = isSupervisorOnlyHandoff(item);
if (!item.conversation_id && !supervisorOnlyHandoff) {
  return fail(404, 'CONVERSATION_NOT_FOUND', 'No existe conversacion local ni un MULTI_MATCH enrutable al supervisor.');
}

const operationAcquired = item.handoff_operation_acquired === true
  || item.handoff_operation_acquired === 't'
  || item.handoff_operation_acquired === 'true';
if (!operationAcquired) {
  const status = String(item.handoff_operation_status || 'unknown');
  const code = status === 'completed' ? 'HANDOFF_ALREADY_PROCESSED'
    : status === 'uncertain' ? 'HANDOFF_REQUIRES_RECONCILIATION'
      : status === 'conversation_not_active' ? 'CONVERSATION_NOT_ACTIVE'
        : 'HANDOFF_IN_PROGRESS';
  return fail(409, code, 'Ya existe una operación de handoff para esta conversación.');
}
if (!/^[0-9a-f-]{36}$/i.test(String(item.handoff_operation_token || ''))) {
  return fail(500, 'HANDOFF_OPERATION_ERROR', 'No se pudo reservar la operación de handoff.');
}

const chatwootBaseUrl = env('RENOV_CHATWOOT_BASE_URL', env('CHATWOOT_BASE_URL')).replace(/\/+$/, '');
const accountId = env('RENOV_CHATWOOT_ACCOUNT_ID', env('CHATWOOT_ACCOUNT_ID'));
const apiToken = env('RENOV_CHATWOOT_API_TOKEN', env('CHATWOOT_API_TOKEN'));
const inboxId = asInt(env('RENOV_CHATWOOT_INBOX_ID', env('CHATWOOT_INBOX_ID')));
if (!chatwootBaseUrl || !accountId || !apiToken) {
  return failReserved(500, 'CHATWOOT_CONFIG_ERROR', 'Variables Chatwoot incompletas: RENOV_CHATWOOT_BASE_URL, RENOV_CHATWOOT_ACCOUNT_ID y RENOV_CHATWOOT_API_TOKEN.');
}
if (!item.chatwoot_conversation_id && !inboxId) {
  return failReserved(500, 'CHATWOOT_CONFIG_ERROR', 'RENOV_CHATWOOT_INBOX_ID es requerido para crear conversaciones nuevas.');
}

const nodeHelpers = this.helpers;
async function httpRequestJson(options) {
  try {
    const response = await nodeHelpers.httpRequest({
      method: options.method,
      url: options.uri,
      headers: options.headers || {},
      body: options.body,
      form: options.form,
      json: true,
      resolveWithFullResponse: true,
      simple: false,
    });
    let status = Number(response.statusCode);
    if (!Number.isFinite(status) && typeof response.status === 'number') status = response.status;
    if (!Number.isFinite(status)) status = 200;
    const body = response.body === undefined ? response : response.body;
    return { ok: status >= 200 && status < 300, status, body: body ?? {} };
  } catch (error) {
    const status = Number(error.statusCode || error.response?.statusCode || error.response?.status || 0);
    const body = error.response?.body || error.error || error;
    return { ok: false, status, body };
  }
}
async function chatwoot(method, path, body) {
  const response = await httpRequestJson({
    method,
    uri: chatwootBaseUrl + '/api/v1/accounts/' + accountId + path,
    headers: { api_access_token: apiToken, 'content-type': 'application/json' },
    body,
  });
  if (!response.ok) {
    throw new Error('Chatwoot ' + method + ' ' + path + ' failed with ' + response.status + ': ' + JSON.stringify(response.body || {}).slice(0, 300));
  }
  return response.body || {};
}

let chatwootConversationId = asInt(item.chatwoot_conversation_id);
let chatwootContactId = null;
let labelStatus = 'skipped';
let assignmentStatus = 'skipped';
let externalEffectStarted = false;

try {
  if (chatwootConversationId) {
    externalEffectStarted = true;
    await chatwoot('POST', '/conversations/' + chatwootConversationId + '/toggle_status', { status: 'open' });
  } else {
    const phoneDigits = String(item.resolved_phone || item.phone || '').replace(/^\+/, '');
    const searchBody = await chatwoot('GET', '/contacts/search?q=' + encodeURIComponent(phoneDigits) + '&include_contacts=true');
    chatwootContactId = extractContactId(firstContact(searchBody) || {});
    if (!chatwootContactId) {
      externalEffectStarted = true;
      chatwootContactId = extractContactId(await chatwoot('POST', '/contacts', buildContactPayload(item)));
    }
    if (!chatwootContactId) throw new Error('No se pudo resolver o crear contacto Chatwoot.');
    externalEffectStarted = true;
    const createdConversation = await chatwoot('POST', '/conversations', { inbox_id: inboxId, contact_id: chatwootContactId, status: 'open' });
    chatwootConversationId = extractConversationId(createdConversation);
    if (!chatwootConversationId) throw new Error('No se pudo crear conversacion Chatwoot.');
  }

  externalEffectStarted = true;
  await chatwoot('POST', '/conversations/' + chatwootConversationId + '/messages', {
    content: buildHandoffNote(item),
    message_type: 'outgoing',
    private: true,
  });

  try {
    await chatwoot('POST', '/conversations/' + chatwootConversationId + '/labels', { labels: buildHandoffLabels(item) });
    labelStatus = 'success';
  } catch (error) {
    labelStatus = 'failed: ' + safeError(error);
  }

  // T-1.16 / functional document 7.2: the conversation goes to the advisor who
  // owns the account. Unassigned, unknown or ambiguous numbers already resolved
  // to the supervision lead upstream. The team is only a fallback for an
  // advisor with no Chatwoot agent mapped yet.
  const assigneeId = asInt(item.advisor_chatwoot_agent_id);
  const teamId = asInt(env('RENOV_CHATWOOT_TEAM_ID'));

  if (assigneeId) {
    try {
      await chatwoot('POST', '/conversations/' + chatwootConversationId + '/assignments', { assignee_id: assigneeId });
      assignmentStatus = 'success:advisor';
    } catch (error) {
      assignmentStatus = 'failed_advisor: ' + safeError(error);
    }
  }

  if (assignmentStatus !== 'success:advisor' && teamId) {
    try {
      await chatwoot('POST', '/conversations/' + chatwootConversationId + '/assignments', { team_id: teamId });
      assignmentStatus = assigneeId ? 'success:team_fallback' : 'success:team';
    } catch (error) {
      assignmentStatus = 'failed: ' + safeError(error);
    }
  }
  if (!assignmentSucceeded(assignmentStatus)) throw new Error('No se pudo asignar la conversacion al asesor o supervisor.');
} catch (error) {
  return failReserved(
    502,
    'CHATWOOT_REQUEST_ERROR',
    'No se pudo completar el handoff en Chatwoot.',
    { chatwoot_error: safeError(error) },
    externalEffectStarted ? 'uncertain' : 'failed',
    chatwootConversationId,
  );
}

let salesforceStatus = 'skipped';
let salesforceHttpStatus = null;
let salesforceError = null;
const salesforceHandoffUrl = env('SALESFORCE_DEV_HANDOFF_URL', env('RENOV_SALESFORCE_HANDOFF_URL'));
if (salesforceHandoffUrl && item.conversation_id) {
  try {
    const baseUrl = env('SALESFORCE_DEV_BASE_URL', 'https://quicklink--uat.sandbox.my.salesforce.com').replace(/\/+$/, '');
    const tokenUrl = env('SALESFORCE_DEV_TOKEN_URL', baseUrl + '/services/oauth2/token');
    const clientId = env('SALESFORCE_DEV_CLIENT_ID');
    const clientSecret = env('SALESFORCE_DEV_CLIENT_SECRET');
    if (!clientId || !clientSecret) throw new Error('missing_salesforce_credentials');
    const tokenResponse = await httpRequestJson({
      method: 'POST',
      uri: tokenUrl,
      headers: { 'content-type': 'application/json' },
      body: { grant_type: 'client_credentials', client_id: clientId, client_secret: clientSecret },
    });
    const tokenBody = tokenResponse.body || {};
    if (!tokenResponse.ok || !tokenBody.access_token) throw new Error('salesforce_auth_failed_' + tokenResponse.status);
    const patchResponse = await httpRequestJson({
      method: env('SALESFORCE_DEV_HANDOFF_METHOD', 'PATCH'),
      uri: salesforceHandoffUrl,
      headers: { authorization: 'Bearer ' + tokenBody.access_token, 'content-type': 'application/json' },
      body: buildSalesforcePatchBody(item, chatwootConversationId),
    });
    salesforceHttpStatus = patchResponse.status;
    if (!patchResponse.ok) {
      throw new Error('salesforce_handoff_patch_failed_' + patchResponse.status + ': ' + JSON.stringify(patchResponse.body || {}).slice(0, 300));
    }
    salesforceStatus = 'success';
  } catch (error) {
    salesforceStatus = 'failed';
    salesforceError = safeError(error);
  }
}

const outcome = {
  chatwootConversationId,
  chatwootContactId,
  labelStatus,
  assignmentStatus,
  salesforceStatus,
  salesforceHttpStatus,
  salesforceError,
  clientMessage: CLIENT_MESSAGE,
  responseCode: salesforceStatus === 'success' ? 200 : 202,
};

return done({
  success: true,
  persist_required: true,
  http_status: outcome.responseCode,
  chatwoot_conversation_id: String(chatwootConversationId),
  chatwoot_contact_id: chatwootContactId ? String(chatwootContactId) : null,
  chatwoot_label_status: labelStatus,
  chatwoot_assignment_status: assignmentStatus,
  salesforce_status: salesforceStatus,
  salesforce_http_status: salesforceHttpStatus,
  salesforce_error: salesforceError,
  client_message: CLIENT_MESSAGE,
  persist_sql: item.conversation_id
    ? buildPersistSql(item, outcome, SCHEMA)
    : buildExternalPersistSql(item, outcome, SCHEMA),
});
